 "content": "def transform(grid):
    # Recolor each connected nonzero rectangle by reversing its outer-to-inner
    # sequence of nested color layers. Collapse repeated adjacent depth colors
    # because some bands are thicker than one cell.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = y + dy, x + dx
                    if (0 <= a < h and 0 <= b < w and grid[a][b] != 0
                            and (a, b) not in seen):
                        seen.add((a, b))
                        stack.append((a, b))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            by_depth = {}
            for y, x in cells:
                depth = min(y - top, bottom - y, x - left, right - x)
                by_depth.setdefault(depth, []).append(grid[y][x])
            depth_colors = [
                max(set(by_depth[d]), key=by_depth[d].count)
                for d in sorted(by_depth)
            ]
            layers = []
            for color in depth_colors:
                if not layers or layers[-1] != color:
                    layers.append(color)
            mapping = dict(zip(layers, reversed(layers)))
